  { id: '3', name: 'Notebook A5', price: 4.99, category: 'Stationery' },
];

let nextId = 4;

const delay = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function getProducts(): Promise<Product[]> {
  await delay(100);
  return [...products];
}

export async function addProduct(data: Omit<Product, 'id'>): Promise<Product> {
  await delay(100);
  const product: Product = { ...data, id: String(nextId++) };
  products.push(product);
  return product;
}

export async function updateProduct(id: string, data: Omit<Product, 'id'>): Promise<Product> {
  await delay(100);
  const idx = products.findIndex((p) => p.id === id);
  if (idx === -1) throw new Error('Product not found');
  products[idx] = { ...data, id };
  return products[idx];
}

export async function deleteProduct(id: string): Promise<void> {
  await delay(100);
  products = products.filter((p) => p.id !== id);
}
"}}
